const IMG={"stpat":"data:image/jpeg;base64,","potluck":"data:image/jpeg;base64,","kite":"data:image/jpeg;base64,","sunset_wide":"data:image/jpeg;base64,","boardwalk_beach":"data:image/jpeg;base64,","boardwalk_sign":"data:image/jpeg;base64,","park_gulf":"data:image/jpeg;base64,","aerial":"data:image/jpeg;base64,","park_dusk":"data:image/jpeg;base64,","sunset_ships":"data:image/jpeg;base64,","park_reflect":"data:image/jpeg;base64,","egrets":"data:image/jpeg;base64,","moorhen":"data:image/jpeg;base64,","park_pond":"data:image/jpeg;base64,","wetland":"data:image/jpeg;base64,"};function hydrateImgs(){document.querySelectorAll('img[data-img]').forEach(function(i){var k=i.getAttribute('data-img');if(IMG[k]){i.src=IMG[k];}});document.querySelectorAll('[data-bg]').forEach(function(e){var k=e.getAttribute('data-bg');if(IMG[k]){e.style.backgroundImage="url('"+IMG[k]+"')";}});}if(document.readyState!=='loading'){hydrateImgs();}else{document.addEventListener('DOMContentLoaded',hydrateImgs);}
